(async()=>{
const {KEY,due,grade,validateBackup}=await import('./core.mjs');
const main=document.querySelector('#main');
let Q=[],records={},view='home',queue=[],pos=0,selected=0,confidence='sure',submitted=false;
let filters={subject:'',month:'',topic:'',search:'',mode:'all'};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const topic=q=>records[q.id]?.topic||q.topic;
const rec=q=>records[q.id]||{};
const usable=()=>Q.filter(q=>!q.incomplete);
let toastTimer;
function toast(s){const el=document.querySelector('#toast');el.textContent=s;el.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.display='none',3000)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(records));return true}catch(e){toast('저장 공간이 부족하거나 저장이 차단되어 있어요. 기록을 내보내 주세요.');return false}}
function persistPosition(){try{localStorage.setItem('hoedok-current',queue[pos]?.id||'')}catch(e){}}
function filtered(){return usable().filter(q=>(!filters.subject||q.subject===filters.subject)&&(!filters.month||q.month===+filters.month)&&(!filters.topic||topic(q)===filters.topic)&&(!filters.search||(q.raw+' '+topic(q)+' '+q.number).includes(filters.search))&&(filters.mode!=='unseen'||!rec(q).attempts)&&(filters.mode!=='review'||rec(q).attempts&&(!rec(q).correct||rec(q).confidence!=='sure'||due(rec(q))))&&(filters.mode!=='saved'||rec(q).bookmarked))}
function setView(v){view=v;document.querySelectorAll('nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===v);if(b.dataset.view===v)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});document.querySelector('#breadcrumb').textContent=({home:'학습 홈',study:'기출문제',topics:'유형별 학습',review:'오답과 복습',saved:'북마크'})[v];render()}
function start(extra={},id){filters={subject:'',month:'',topic:'',search:'',mode:'all',...extra};queue=filtered();pos=id?Math.max(0,queue.findIndex(q=>q.id===id)):0;reset();setView('study');persistPosition();window.scrollTo(0,0)}
function reset(){selected=0;confidence='sure';submitted=false}
function empty(title,desc){return `<div class="empty"><h2>${title}</h2><p>${desc}</p><button class="secondary" data-action="all">전체 기출 보기</button></div>`}
const chevron='<svg viewBox="0 0 20 20" fill="none" aria-hidden="true"><path d="m7.5 5 5 5-5 5" stroke="currentColor" stroke-width="1.4"/></svg>';
function home(){
 const all=usable(), solved=all.filter(q=>rec(q).attempts), right=solved.filter(q=>rec(q).correct).length;
 const review=all.filter(q=>rec(q).attempts&&(!rec(q).correct||rec(q).confidence!=='sure'||due(rec(q))));
 let last;try{last=localStorage.getItem('hoedok-current')}catch(e){}
 const rate=solved.length?Math.round(right/solved.length*100)+'%':'—';
 main.innerHTML=`<div class="page-heading"><div><h1>2026년 기출문제</h1><p class="subtitle">회차를 골라 풀고, 공식 확정답안으로 채점하세요.</p></div><div class="heading-action"><button class="primary" data-action="${last?'resume':'all'}">${last?'이어서 풀기':'학습 시작'}</button></div></div>
 <dl class="summary-strip"><div class="summary-item"><dt>학습한 문제</dt><dd>${solved.length}<span>/ ${all.length}</span></dd></div><div class="summary-item"><dt>최근 답 정답률</dt><dd>${rate}</dd></div><div class="summary-item"><dt>복습할 문제</dt><dd>${review.length}<span>문항</span></dd></div></dl>
 <div class="home-columns"><div><section aria-labelledby="sessions-title"><div class="section-heading"><h2 id="sessions-title">회차별 문제</h2><span class="small">6개 회차 / 총 480문항</span></div><table class="exam-table"><caption class="visually-hidden">2026년 회차별 기출문제와 학습 현황</caption><thead><tr><th scope="col">시행 회차</th><th scope="col">학습 가능</th><th scope="col">학습 현황</th><th scope="col"><span class="visually-hidden">문제 풀기</span></th></tr></thead><tbody>${[1,3,5,6,7,9].map(m=>{const qs=all.filter(q=>q.month===m),done=qs.filter(q=>rec(q).attempts).length;return `<tr><td><button class="exam-name" data-month="${m}"><span>2026년</span>${m}월</button></td><td>${qs.length}문항</td><td><div class="progress-label"><b>${done}</b> / ${qs.length}</div><div class="progress" aria-hidden="true"><i style="width:${done/qs.length*100}%"></i></div></td><td><button class="exam-open" data-month="${m}" aria-label="2026년 ${m}월 기출문제 풀기">풀기 ${chevron}</button></td></tr>`}).join('')}</tbody></table></section>
 <section class="topic-section" aria-labelledby="quick-topic-title"><div class="section-heading"><h2 id="quick-topic-title">유형 골라 풀기</h2><button class="text-btn" data-view="topics">전체 유형</button></div><div class="topic-preview">${['영세율·면세','공급시기','재고자산','세무조정·소득처분'].map(t=>`<button class="topic-chip" data-topic="${t}"><span>${t}</span><small>${all.filter(q=>topic(q)===t).length}문항</small></button>`).join('')}</div></section></div>
 <div class="home-side"><section class="review-summary" aria-labelledby="review-title"><h2 id="review-title">다시 풀 문제</h2><div class="review-number">${review.length}<span>문항</span></div><p>${review.length?'틀렸거나 확신이 부족했던 문제와<br>복습일이 된 문제를 모았습니다.':'아직 복습할 문제가 없습니다.<br>풀이를 시작하면 여기에 모입니다.'}</p><button class="secondary" data-action="review">${review.length?'복습 시작':'복습 목록 보기'}</button></section><section class="subject-section" aria-labelledby="subject-title"><h2 id="subject-title">과목별 학습</h2>${['재무회계','세무회계'].map(subject=>{const qs=all.filter(q=>q.subject===subject);return `<button class="subject-row" data-subject="${subject}"><span><strong>${subject}</strong><small>${qs.length}문항 / ${qs.filter(q=>rec(q).attempts).length}문항 학습</small></span>${chevron}</button>`}).join('')}</section></div></div>
 <details class="source-notice"><summary>자료 안내 / 보기 누락 3문항</summary><p>문제와 확정답안 12개 파일을 연결했습니다. 9월 47, 50, 55번은 첨부 MD의 ④ 보기가 누락되어 기본 출제에서 제외했습니다. <button class="text-btn" data-action="issues">누락된 원문 확인</button></p></details>`;
}
function filterBar(){return `<div class="filters"><select aria-label="과목" id="f-subject"><option value="">전체 과목</option>${['재무회계','세무회계'].map(s=>`<option ${filters.subject===s?'selected':''}>${s}</option>`).join('')}</select><select aria-label="회차" id="f-month"><option value="">전체 회차</option>${[1,3,5,6,7,9].map(m=>`<option value="${m}" ${+filters.month===m?'selected':''}>2026년 ${m}월</option>`).join('')}</select><select aria-label="유형" id="f-topic"><option value="">전체 유형</option>${[...new Set(usable().map(topic))].sort().map(t=>`<option ${filters.topic===t?'selected':''}>${esc(t)}</option>`).join('')}</select><select id="f-mode" aria-label="학습 상태">${[['all','전체 문제'],['unseen','미학습 우선'],['review','오답과 복습'],['saved','북마크']].map(([v,l])=>`<option value="${v}" ${filters.mode===v?'selected':''}>${l}</option>`).join('')}</select><input id="f-search" type="search" placeholder="지문 / 유형 / 문항번호 검색" aria-label="문제 검색" value="${esc(filters.search)}"></div>`}
function study(){main.innerHTML=`<h1>기출문제 풀기</h1><p class="subtitle">정답은 제출 후에만 공개돼요. 확신도도 함께 기록해 보세요.</p>${filterBar()}<div id="question-area"></div>`;question();}
function question(){const area=document.querySelector('#question-area');const q=queue[pos];if(!q){area.innerHTML=empty('조건에 맞는 문제가 없어요','과목이나 유형을 바꾸어 다시 찾아보세요.');return}
 const r=rec(q);area.innerHTML=`<div class="study-layout"><article class="question"><div class="question-meta"><span class="pill">${q.subject}</span><span>2026년 ${q.month}월 / ${q.number}번</span><span>${q.format}</span><button class="bookmark" data-action="bookmark" aria-label="${r.bookmarked?'북마크 해제':'북마크 추가'}" aria-pressed="${!!r.bookmarked}">${r.bookmarked?'★':'☆'}</button></div><div class="question-body">${q.html}</div><div class="options" role="group" aria-label="정답 선택">${[1,2,3,4].map(a=>`<button class="option ${selected===a?'selected':''} ${submitted&&a===q.answer?'correct':''} ${submitted&&selected===a&&a!==q.answer?'wrong':''}" data-answer="${a}" aria-pressed="${selected===a}" ${submitted?'disabled':''}><span class="num">${a}</span><div>${q.options.length?q.options[a-1]:'표의 '+['①','②','③','④'][a-1]+'번 보기'}</div>${submitted&&a===q.answer?'<span class="answer-label">정답</span>':''}</button>`).join('')}</div><div class="confidence"><span>이 답에 얼마나 확신하나요?</span>${[['sure','확실해요'],['unsure','헷갈려요'],['guess','찍었어요']].map(([v,l])=>`<button data-confidence="${v}" class="${confidence===v?'selected':''}" aria-pressed="${confidence===v}" ${submitted?'disabled':''}>${l}</button>`).join('')}</div><div class="question-actions"><button class="ghost" data-action="prev" ${pos===0?'disabled':''}>이전</button><span class="small muted">${pos+1} / ${queue.length}</span>${submitted?`<button class="primary" data-action="next">${pos===queue.length-1?'학습 마치기':'다음 문제'}</button>`:`<button class="primary" data-action="submit" ${!selected?'disabled':''}>정답 제출하기</button><button class="ghost" data-action="next">건너뛰기</button>`}</div>${submitted?result(q):''}</article><div class="study-side"><div class="panel"><h3>이 문제의 유형</h3><span class="pill">${q.unit}</span><p style="color:var(--ink);margin-top:10px">${esc(topic(q))}</p><p>자동 분류 초안 / 직접 수정 가능</p><details class="type-fields"><summary>유형 수정하기</summary><label for="custom-topic">나의 유형 이름</label><input id="custom-topic" value="${esc(topic(q))}" maxlength="80"><button class="secondary" data-action="save-topic">분류 저장</button></details></div><div class="panel"><h3>풀이 노트</h3><textarea id="note" aria-label="나의 풀이 노트" maxlength="20000" placeholder="헷갈린 개념, 계산 과정, 나만의 해설을 남겨보세요.">${esc(r.note||'')}</textarea><p style="margin-bottom:0">입력 내용은 자동 저장됩니다.</p></div><div class="panel"><h3>문제 풀이 기준</h3><p style="margin-bottom:0">문제에 제시된 연도·세율·회계기준을 적용하세요. 기록은 현재 기기의 브라우저에 저장됩니다.</p></div></div></div>`;
}
function result(q){const r=rec(q);return `<section class="result ${r.correct?'':'wrong-result'}" aria-live="polite"><h3>${r.correct?'정답입니다':'오답입니다'}</h3><p>선택한 답 <b>${r.answer}번</b> <span class="slash">/</span> 공식 확정답안 <b>${q.answer}번</b></p><p class="source">채점 출처: ${esc(q.answerSource)} / ${q.number}번</p><p class="small muted">다음 복습: ${new Date(r.dueAt).toLocaleDateString('ko-KR',{timeZone:'Asia/Seoul'})} / ${r.confidence==='sure'?'확실해요':r.confidence==='unsure'?'헷갈려요':'찍었어요'}</p><div class="concept"><h3>문제 해설</h3><p class="explanation-text">${esc(q.explanation||'이 문제의 해설은 준비 중입니다.')}</p><p class="source">${esc(q.explanationOrigin||'학습용 자체 해설')} / 문제에 제시된 회계기준·연도·세율을 적용했습니다. 공식 확정답안과는 별도로 작성한 해설입니다.</p></div><details><summary>문제 출처 확인</summary><p class="source">${esc(q.source)} / ${q.number}번<br>첨부 원문과 확정답안을 연결했습니다.</p></details></section>`}
function topics(){const groups=new Map();for(const q of usable()){const t=topic(q);if(!groups.has(t))groups.set(t,[]);groups.get(t).push(q)}main.innerHTML=`<h1>유형별 학습</h1><p class="subtitle">같은 유형을 모아 풀고, 이해한 범위를 확인하세요. 자동 분류는 각 문제에서 수정할 수 있어요.</p><div class="topic-grid" style="margin-top:28px">${[...groups].sort((a,b)=>a[1][0].subject.localeCompare(b[1][0].subject)).map(([t,qs])=>{let done=qs.filter(q=>rec(q).attempts).length;return `<button class="topic-card" data-topic="${esc(t)}"><span class="pill">${qs[0].subject} / ${qs[0].unit}</span><h3>${esc(t)}</h3><p>${qs.length}문항 / 학습 ${done}문항</p><div class="progress"><i style="width:${done/qs.length*100}%"></i></div><div class="progress-label"><span>${done===0?'미학습':done===qs.length?'학습 완료':'학습 중'}</span><span>${Math.round(done/qs.length*100)}%</span></div></button>`}).join('')}</div>`}
function list(saved=false){const qs=usable().filter(q=>saved?rec(q).bookmarked:rec(q).attempts&&(!rec(q).correct||rec(q).confidence!=='sure'||due(rec(q))));main.innerHTML=`<h1>${saved?'북마크':'오답과 복습'}</h1><p class="subtitle">${saved?'별표를 눌러 모아둔 문제를 다시 만나보세요.':'오답·불확실한 정답·복습일이 된 문제를 모았어요.'}</p><div class="section-heading"><h2>${qs.length}문항</h2>${qs.length?`<button class="primary" data-action="${saved?'saved-study':'review'}">모아서 풀기</button>`:''}</div>${qs.length?qs.map(q=>`<div class="list-row"><div><h3>${esc(topic(q))}</h3><p>${q.month}월 / ${q.subject} ${q.number}번 <span class="slash">/</span> ${!rec(q).attempts?'미학습':!rec(q).correct?'오답':rec(q).confidence!=='sure'?'확신 부족':'복습일 도래'}</p></div><button class="secondary" data-question="${q.id}">풀어보기</button></div>`).join(''):empty(saved?'아직 북마크한 문제가 없어요':'지금은 복습할 문제가 없어요',saved?'문제 오른쪽 위의 ☆를 누르면 여기에 모여요.':'기출을 풀면 복습할 문제를 자동으로 모아드려요.')}`}
function render(){if(view==='home')home();else if(view==='study')study();else if(view==='topics')topics();else list(view==='saved')}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 if(b.dataset.view){if(b.dataset.view==='study'&&!queue.length)start();else setView(b.dataset.view);return}
 if(b.dataset.subject){start({subject:b.dataset.subject});return}if(b.dataset.month){start({month:b.dataset.month});return}if(b.dataset.topic){start({topic:b.dataset.topic});return}if(b.dataset.question){start({},b.dataset.question);return}
 if(b.dataset.answer){selected=+b.dataset.answer;question();return}if(b.dataset.confidence){confidence=b.dataset.confidence;question();return}
 const q=queue[pos],a=b.dataset.action;
 if(a==='all')start();else if(a==='resume'){let id;try{id=localStorage.getItem('hoedok-current')}catch(e){}start({},id)}
 else if(a==='review')start({mode:'review'});else if(a==='saved-study')start({mode:'saved'});
 else if(a==='submit'&&q&&selected){records[q.id]=grade(rec(q),selected,q.answer,confidence);save();submitted=true;question()}
 else if(a==='next'){if(pos<queue.length-1){pos++;reset();question();persistPosition();window.scrollTo(0,0)}else{toast('선택한 문제를 모두 살펴봤어요. 수고하셨습니다!');setView('home')}}
 else if(a==='prev'&&pos>0){pos--;reset();question();persistPosition()}
 else if(a==='bookmark'&&q){records[q.id]={...rec(q),bookmarked:!rec(q).bookmarked};save();question();toast(rec(q).bookmarked?'북마크에 저장했어요.':'북마크를 해제했어요.')}
 else if(a==='save-topic'&&q){const t=document.querySelector('#custom-topic').value.trim();if(t){records[q.id]={...rec(q),topic:t};save();question();toast('유형을 저장했어요.')}}
 else if(a==='issues'){main.innerHTML=`<h1>첨부 원문 확인 필요</h1><p class="subtitle">누락된 보기를 임의로 만들지 않았습니다. 이 문항은 기본 출제에서 제외됩니다.</p>${Q.filter(q=>q.incomplete).map(q=>`<article class="question" style="margin:18px 0"><h2>${q.month}월 ${q.number}번</h2><div class="notice">④ 보기가 첨부 MD에 없습니다.</div><div class="question-body">${q.html}</div><p class="source">${esc(q.source)}</p></article>`).join('')}<button class="secondary" data-view="home">학습 홈으로</button>`}
});
document.addEventListener('input',e=>{if(e.target.id==='note'&&queue[pos]){const q=queue[pos];records[q.id]={...rec(q),note:e.target.value};save()}});
let searchTimer;
document.addEventListener('input',e=>{if(e.target.id==='f-search'){clearTimeout(searchTimer);const value=e.target.value;searchTimer=setTimeout(()=>{filters.search=value;queue=filtered();pos=0;reset();question();persistPosition()},200)}});
document.addEventListener('change',e=>{const k=({'f-subject':'subject','f-month':'month','f-topic':'topic','f-mode':'mode'})[e.target.id];if(k){filters[k]=e.target.value;queue=filtered();pos=0;reset();question();persistPosition()}});
document.querySelector('.file-label').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();document.querySelector('#import').click()}});
document.querySelector('#backup-open').onclick=()=>document.querySelector('#backup').showModal();
document.querySelector('#export').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),records},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='accounting-pass-backup-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);document.querySelector('#backup-status').textContent='백업 파일을 내보냈어요.'};
document.querySelector('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>10*1024*1024)throw Error('10MB 이하 파일을 선택해 주세요.');const parsed=validateBackup(JSON.parse(await f.text()),new Set(Q.map(q=>q.id)));for(const [id,r]of Object.entries(parsed))if(r.answer)r.correct=r.answer===Q.find(q=>q.id===id).answer;records={...records,...parsed};if(save()){document.querySelector('#backup-status').textContent='기록을 가져왔어요.';render()}}catch(error){document.querySelector('#backup-status').textContent=error.message}e.target.value=''};
try{const response=await fetch('./questions.json');if(!response.ok)throw Error('문제 파일을 읽을 수 없습니다.');Q=await response.json();try{const stored=JSON.parse(localStorage.getItem(KEY)||'{}');records=validateBackup({version:1,records:stored},new Set(Q.map(q=>q.id)))}catch(e){toast('기존 기록을 읽을 수 없어요. 브라우저 저장 설정을 확인해 주세요.')}setView('home')}catch(e){main.innerHTML='<h1>문제를 불러오지 못했어요.</h1><p>파일을 직접 열었다면 로컬 서버 또는 Netlify에서 실행해 주세요.</p>';}
})();
